        string location=Get(entry,"path","").AsString();var raw=Get(entry,"preset");var preset=raw.VariantType==Variant.Type.Object?raw.AsGodotObject() as Resource:null;if(preset==null||location.Length==0){notice(o,"Choose a saved preset before editing tags.");return;}string digest=Godot.FileAccess.GetSha256(location);if(digest.Length==0){notice(o,"The preset file is missing or unreadable. Refresh the library first.");return;}var current=ResourceLoader.Load(location,"",ResourceLoader.CacheMode.Ignore);if(!IsScript(current,"res://Workspaces/AudioWorkspace/KiwiAudioPreset.cs")||current.Get("id").AsString()!=preset.Get("id").AsString()||Godot.FileAccess.GetSha256(location)!=digest){notice(o,"The preset changed or is unreadable. Refresh the library before editing tags.");return;}var owner=Session(o);string identity=current.Get("id").AsString();using var library=new AudioLibraryOperations();name_dialog(o,"Preset tags (comma separated, up to 32)",string.Join(", ",library.preset_tags(current)),Callable.From<string>(text=>{if(!o.IsInsideTree()||!o.IsVisibleInTree()||Session(o)!=owner)return;var tags=new System.Collections.Generic.List<string>();var seen=new System.Collections.Generic.HashSet<string>();foreach(string value in text.Split(',',StringSplitOptions.RemoveEmptyEntries)){string tag=value.Trim();if(tag.Length==0)continue;if(ScalarLength(tag)>128){notice(o,"Each preset tag may contain at most 128 characters.");return;}string key=tag.ToLowerInvariant();if(seen.Contains(key))continue;if(tags.Count>=32){notice(o,"Use at most 32 distinct tags per preset.");return;}tags.Add(tag);seen.Add(key);}string problem=save_preset_tags(location,digest,identity,tags.ToArray());if(problem.Length>0){notice(o,problem);return;}var browser=Field<Control>(o,"library");browser.Call("reload");o.Set("_library_entry",Dict(browser,"current").Duplicate());refresh_inspector(o);Field<Label>(o,"status").Text="Saved preset tags. Use library search or the tag/type filters to find it.";}),true);
    }
