        string root=ProjectSettings.GlobalizePath("user://audio_workspace/presets").SimplifyPath(),absolute=ProjectSettings.GlobalizePath(location).SimplifyPath();using var access=DirAccess.Open(root);if(access==null||absolute.GetBaseDir()!=root||absolute.GetExtension().ToLowerInvariant()!="tres"||access.IsLink(absolute.GetFile()))return "Only native presets inside the library folder can be tagged.";if(digest.Length==0||Godot.FileAccess.GetSha256(absolute)!=digest)return "The preset changed after the tag editor opened. Refresh and edit its current version.";var original=ResourceLoader.Load(absolute,"",ResourceLoader.CacheMode.Ignore);if(!IsScript(original,"res://Workspaces/AudioWorkspace/KiwiAudioPreset.cs")||original.Get("id").AsString()!=identity)return "The selected preset was replaced or is unreadable. Nothing was saved.";var copy=original.Duplicate(false);if(!IsScript(copy,"res://Workspaces/AudioWorkspace/KiwiAudioPreset.cs"))return "Could not copy the preset metadata. Nothing was saved.";copy.ResourcePath="";copy.Set("tags",(string[])tags.Clone());var data=copy.Get("data").AsGodotDictionary();if(copy.Get("kind").AsString()=="pattern"||data.ContainsKey("tags")){data=data.Duplicate(false);var values=new GArray();foreach(string tag in tags)values.Add(tag);data["tags"]=values;copy.Set("data",data);}using var crypto=new Crypto();string token=Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant(),temporary=absolute.GetBaseName()+".tags-writing-"+token+".tres",backup=absolute+".tags-backup-"+token;if(Godot.FileAccess.FileExists(temporary)||Godot.FileAccess.FileExists(backup))return "Could not reserve a new preset save name. Try again.";var error=ResourceSaver.Save(copy,temporary);if(error!=Error.Ok){if(Godot.FileAccess.FileExists(temporary))DirAccess.RemoveAbsolute(temporary);return "The preset tags could not be saved ("+error+"). The original is intact.";}if(access.IsLink(absolute.GetFile())||Godot.FileAccess.GetSha256(absolute)!=digest){DirAccess.RemoveAbsolute(temporary);return "The preset changed while saving. Its newer version was left intact.";}error=DirAccess.RenameAbsolute(absolute,backup);if(error!=Error.Ok){DirAccess.RemoveAbsolute(temporary);return "Could not preserve the previous preset. Tags were not changed.";}error=DirAccess.RenameAbsolute(temporary,absolute);if(error!=Error.Ok){var restored=DirAccess.RenameAbsolute(backup,absolute);if(Godot.FileAccess.FileExists(temporary))DirAccess.RemoveAbsolute(temporary);return "Could not publish preset tags. "+(restored==Error.Ok?"The previous preset was restored.":"The previous preset is retained at "+backup);}return "";
